const MAX_STORED_CLEAR_TIME_MS = 24 * 60 * 60 * 1000;

export function sanitizeProgress(value) {
  const source = value && typeof value === "object" ? value : {};
  const rawIndex = Number(source.unlockedLevelIndex);
  const unlockedLevelIndex = Number.isFinite(rawIndex)
    ? clamp(Math.trunc(rawIndex), 0, LEVELS.length - 1)
    : DEFAULT_PROGRESS.unlockedLevelIndex;

  const stars = {};
  const bestTimeMs = {};
  for (const level of LEVELS) {
    const rawStars = Number(source.stars?.[level.id]);
    if (Number.isFinite(rawStars)) stars[level.id] = clamp(Math.trunc(rawStars), 0, 3);
    const rawTime = Number(source.bestTimeMs?.[level.id]);
    if (Number.isFinite(rawTime) && rawTime > 0 && rawTime <= MAX_STORED_CLEAR_TIME_MS) {
      bestTimeMs[level.id] = rawTime;
    }
  }

  const haptics = typeof source.settings?.haptics === "boolean"
    ? source.settings.haptics
    : DEFAULT_PROGRESS.settings.haptics;
  const sound = typeof source.settings?.sound === "boolean"
    ? source.settings.sound
    : DEFAULT_PROGRESS.settings.sound;
  const storedScheme = source.settings?.controlScheme;
  const controlScheme = storedScheme === "tilt" || storedScheme === "joystick"
    ? storedScheme
    : DEFAULT_PROGRESS.settings.controlScheme;
  const cameraMode = ["action", "command"].includes(source.settings?.cameraMode)
    ? source.settings.cameraMode : DEFAULT_PROGRESS.settings.cameraMode;
  const dailyReminders = typeof source.settings?.dailyReminders === "boolean"
    ? source.settings.dailyReminders
    : DEFAULT_PROGRESS.settings.dailyReminders;
  const warCabinetOnboardingSeen = typeof source.settings?.warCabinetOnboardingSeen === "boolean"
    ? source.settings.warCabinetOnboardingSeen
    : DEFAULT_PROGRESS.settings.warCabinetOnboardingSeen;
  const modeGuidesSeen = Object.fromEntries(
    Object.keys(DEFAULT_PROGRESS.settings.modeGuidesSeen).map((mode) => [
      mode,
      source.settings?.modeGuidesSeen?.[mode] === true,
    ]),
  );

  return {
    unlockedLevelIndex,
    stars,
    bestTimeMs,
    settings: {
      haptics,
      sound,
      controlScheme,
      cameraMode,
      dailyReminders,
      warCabinetOnboardingSeen,
      modeGuidesSeen,
    },
  };
}

