// A single independent encounter; it never changes the ten-sector campaign.
// A preparation phase, which this game otherwise has none of. Every other
// mode starts by reacting; this one starts by committing. Ten seconds with
// the map visible and nothing moving, four mines to place, and then you live
// with the plan - there are no take-backs once the clock runs out, which is
// what makes it a decision rather than a reflex.
//
// The mine was close to a dead mechanic before this: one per level, dropped
// under fire, usually wasted. Four placed deliberately is a different verb.
// A reversal of every other mode: here the gun is not the target, it is the
// thing looking for you. Sentries watch a corridor system and shell anything
// they can see; you have no base to defend and nothing to kill, only a run to
// the extraction point at the far end.
//
// That makes cover the whole game. Every other mode rewards firepower and
// position; this one rewards reading sightlines and moving between walls,
// which is why the grids are corridors and blind corners rather than open
// lanes with cover dotted through them.
//
// It runs four boards back to back rather than one. A single maze is over in
// well under a minute, which made "labyrinth" a promise the mode did not
// keep; reaching an extraction now breaks you into the next section with the
// damage you are carrying and the clock still running, and only the fourth
// one ends the run.
export const LABYRINTH_STAGES = Object.freeze([]);

export const LABYRINTH_LEVEL = Object.freeze({id:"disabled-labyrinth_level",base:{},grid:[],waveEntries:[],spawnPoints:[]});

// Which board a run is currently on. Every level that is not staged answers
// with itself, so callers never branch on whether stages exist.
export function stageOf(level, index = 0) {
  const stages = level.stages;
  if (!stages || stages.length === 0) return level;
  return stages[clamp(Math.trunc(index) || 0, 0, stages.length - 1)];
}

export function stageCount(level) {
  return level.stages?.length ?? 1;
}

export const SAPPER_LEVEL = Object.freeze({id:"disabled-sapper_level",base:{},grid:[],waveEntries:[],spawnPoints:[]});

// Escort reuses the base damage/collision contract, but its target moves.
// A clear road and nearby escort are both required; killing a wave is not victory.
export const ESCORT_LEVEL = Object.freeze({id:"disabled-escort_level",base:{},grid:[],waveEntries:[],spawnPoints:[]});

export function defeatExplanation(state) {
  if (state.result?.outcome !== "lost") return "";
  const baseLost = state.result.reason === "base-destroyed";
  const subject = baseLost ? state.escort ? "Convoy destroyed" : "Base destroyed" : "Tank destroyed";
  const damage = state.lastDamage;
  if (!damage) return `${subject}.`;
  if (!Number.isFinite(damage.sourceX) && !damage.artillery) return `${subject} — incoming fire. Use cover and intercept attackers.`;
  if (damage.artillery) return `${subject} — artillery impact. ${baseLost ? "Hunt the artillery — its shells clear walls." : "Leave the marked blast zone."}`;
  const lane = damage.sourceX < 120 ? "left" : damage.sourceX > 240 ? "right" : "centre";
  return `${subject} — ${baseLost ? `${lane} approach breached` : `fire from the ${lane}`}. ${baseLost ? "Intercept attackers before they reach it." : "Use cover before returning fire."}`;
}

// Sentry guns for escape levels. Deliberately slow to fire and quick to
// forget: the mode is about reading sightlines and moving between cover, not
// about out-running a reflex.
export const SENTRY_RULES = Object.freeze({
  watchRange: 320, reloadMs: 3_200, openingMs: 1_800, reacquireMs: 1_400,
});

// A stage may sharpen its guns. Later sections of a labyrinth run watch
// further and reload faster, which is what makes six boards an escalation
// rather than the same board six times.
export function sentryRulesFor(level, stageIndex = 0) {
  const overrides = stageOf(level, stageIndex).sentryRules;
  const rules = overrides ? { ...SENTRY_RULES, ...overrides } : SENTRY_RULES;
  return level.autoFire === false ? { ...rules,
    openingMs: rules.openingMs * 1.5, reloadMs: rules.reloadMs * 1.35,
    reacquireMs: rules.reacquireMs * 1.35,
  } : rules;
}

// How long is left before the wave is released. Zero on every other level.
export function prepRemainingMs(state) {
  const level = levelById(state.levelId);
  return Math.max(0, (level.prepMs ?? 0) - state.elapsedMs);
}

// What an escape level needs on screen: whether a gun can see you right now,
// and how far the run still has to go. Exposure is the only state that
// matters moment to moment, so it is computed from the same line of sight the
// sentries themselves use rather than approximated.
export function escapeIntel(state) {
  const level = levelById(state.levelId);
  if (!level.extraction) return null;
  const stage = stageOf(level, state.stage ?? 0);
  const watchers = state.enemies.filter((enemy) => enemy.sentry && enemy.hp > 0);
  const rules = sentryRulesFor(level, state.stage ?? 0);
  const exposedTo = watchers.filter((enemy) =>
    distance(enemy, state.player) <= rules.watchRange
    && hasLineOfSight(state.grid, enemy.x, enemy.y, state.player.x, state.player.y));
  return {
    exposed: exposedTo.length > 0,
    watchers: exposedTo.length,
    distanceToExtraction: Math.round(distance(state.player, stage.extraction)),
    extraction: stage.extraction,
    // A run four boards long has to say which one you are on, or reaching
    // an extraction reads as the game refusing to end.
    stage: (state.stage ?? 0) + 1,
    stageCount: stageCount(level),
    stageName: stage.name ?? level.name,
  };
}

export function levelById(levelId) { if(levelId!=="outer-wall") throw new RangeError("Only the demo sector is available"); return LEVELS[0]; }

export function clamp(value, minimum, maximum) {
  return Math.min(maximum, Math.max(minimum, value));
}

export function normalizeInputVector(vector) {
  const x = vector?.x ?? 0;
  const y = vector?.y ?? 0;
  const magnitude = Math.hypot(x, y);
  if (magnitude <= 1 || magnitude === 0) return { x, y };
  return { x: x / magnitude, y: y / magnitude };
}

export function applyRadialDeadzone(vector, deadzone = 0.12) {
  const normalized = normalizeInputVector(vector);
  const magnitude = Math.hypot(normalized.x, normalized.y);
  const safeDeadzone = clamp(deadzone, 0, 0.95);
  if (magnitude <= safeDeadzone) return { x: 0, y: 0 };
  const scaledMagnitude = (magnitude - safeDeadzone) / (1 - safeDeadzone);
  return {
    x: (normalized.x / magnitude) * scaledMagnitude,
    y: (normalized.y / magnitude) * scaledMagnitude,
  };
}

export function joystickVector(dx, dy, maxRadius) {
  if (maxRadius <= 0) return { x: 0, y: 0 };
  return normalizeInputVector({ x: dx / maxRadius, y: dy / maxRadius });
}

export function tiltToVector(orientation, baseline, tiltRangeDeg = 18) {
  const deltaGamma = (orientation?.gamma ?? 0) - (baseline?.gamma ?? 0);
  const deltaBeta = (orientation?.beta ?? 0) - (baseline?.beta ?? 0);
  return normalizeInputVector({
    x: clamp(deltaGamma / tiltRangeDeg, -1, 1),
    y: clamp(deltaBeta / tiltRangeDeg, -1, 1),
  });
}

function normalizeAngle(angle) {
  let a = angle % (Math.PI * 2);
  if (a > Math.PI) a -= Math.PI * 2;
  if (a < -Math.PI) a += Math.PI * 2;
  return a;
}

function distance(a, b) {
  return Math.hypot(a.x - b.x, a.y - b.y);
}

function cellAt(grid, x, y) {
  const col = clamp(Math.floor(x / TILE), 0, GRID_COLS - 1);
  const row = clamp(Math.floor(y / TILE), 0, GRID_ROWS - 1);
  return grid[row]?.[col] ?? ".";
}

export function terrainAt(grid, x, y) {
  return cellAt(grid, x, y);
}

export function terrainSpeedMultiplier(grid, x, y) {
  return terrainAt(grid, x, y) === "~" ? TACTICAL_RULES.mudSpeedMultiplier : 1;
}

function circleIntersectsTile(x, y, radius, col, row_) {
  const tileX = col * TILE;
  const tileY = row_ * TILE;
  const closestX = clamp(x, tileX, tileX + TILE);
  const closestY = clamp(y, tileY, tileY + TILE);
  const dx = x - closestX;
  const dy = y - closestY;
  return dx * dx + dy * dy < radius * radius;
}

function findBlockingCell(grid, x, y, radius, blockingTypes) {
  if (x - radius < 0 || x + radius > WORLD.width || y - radius < 0 || y + radius > WORLD.height) {
    return { row: -1, col: -1, type: "bounds" };
  }
  const minCol = Math.max(0, Math.floor((x - radius) / TILE));
  const maxCol = Math.min(GRID_COLS - 1, Math.floor((x + radius) / TILE));
  const minRow = Math.max(0, Math.floor((y - radius) / TILE));
  const maxRow = Math.min(GRID_ROWS - 1, Math.floor((y + radius) / TILE));
  for (let r = minRow; r <= maxRow; r += 1) {
    for (let c = minCol; c <= maxCol; c += 1) {
      const cell = grid[r][c];
      if (blockingTypes.includes(cell) && circleIntersectsTile(x, y, radius, c, r)) {
        return { row: r, col: c, type: cell };
      }
    }
  }
  return null;
}

// Returns the first solid movement cell (or arena boundary) a circle
// overlaps. Scrub is traversable, so it is intentionally absent here.
export function findSolidCell(grid, x, y, radius) {
  return findBlockingCell(grid, x, y, radius, "#%");
}

// Direct shells cannot cross hard cover or dense scrub. The swept sample
// closes the endpoint-only tunnelling gap when stepLevel is called with a
// larger-than-normal dt, while normal 60Hz play uses only a few samples.
// Exported so a test can ask the same question the shell asks, rather than the
// thinner one hasLineOfSight answers - the gap between those two is exactly
// where a tank shelled a corner for 60 seconds believing it was in position.
export function projectileBlockedBetween(grid, x0, y0, x1, y1, radius) {
  return Boolean(traceProjectileBlocker(grid, x0, y0, x1, y1, radius));
}

function traceProjectileBlocker(grid, x0, y0, x1, y1, radius) {
  const distancePx = Math.hypot(x1 - x0, y1 - y0);
  const steps = Math.max(1, Math.ceil(distancePx / Math.max(1, radius)));
  for (let index = 1; index <= steps; index += 1) {
    const progress = index / steps;
    const x = x0 + (x1 - x0) * progress;
    const y = y0 + (y1 - y0) * progress;
    const hit = findBlockingCell(grid, x, y, radius, "#%^");
    if (hit) return { ...hit, x, y };
  }
  return null;
}

function setCell(grid, r, c, char) {
  const next = grid.slice();
  next[r] = next[r].slice(0, c) + char + next[r].slice(c + 1);
  return next;
}

// When a diagonal move is blocked on both axes at once from the very same
// starting point, the circle is typically resting against the corner POINT
// of a single wall tile (a concave, inward corner - e.g. the foot of an
// L-shaped brick formation) rather than genuinely boxed in. Sliding around
// that point means moving tangentially to the circle-vs-corner contact:
// perpendicular to the line from the corner to the circle's centre. Unlike a
// trial-and-error fan of angles, this reads the escape direction straight
// off the blocking tile's own geometry, so it always slides along the
// correct side of the corner instead of guessing and occasionally sending
// the tank the wrong way.
function cornerSlide(grid, x, y, dx, dy, radius, blocker) {
  if (!blocker || blocker.row < 0 || blocker.col < 0) return null;
  const tileX = blocker.col * TILE;
  const tileY = blocker.row * TILE;
  const nearestX = clamp(x, tileX, tileX + TILE);
  const nearestY = clamp(y, tileY, tileY + TILE);
  const normalX = x - nearestX;
  const normalY = y - nearestY;
  const normalLength = Math.hypot(normalX, normalY);
  if (normalLength < 1e-6) return null;
  const tangentX = -normalY / normalLength;
  const tangentY = normalX / normalLength;
  const forward = dx * tangentX + dy * tangentY >= 0 ? 1 : -1;
  const stepDistance = Math.hypot(dx, dy);
  // Try the side of the tangent that best matches the input direction
  // first, but fall back to the opposite side if something else (most
  // commonly the arena boundary, which this tile's own geometry knows
  // nothing about) blocks that preferred side. Either side is genuine
  // clearance along this wall; escaping the wedge beats freezing solid,
  // even if the first frame's nudge isn't quite the intended heading.
  for (const sign of [forward, -forward]) {
    const cx = x + tangentX * sign * stepDistance;
    const cy = y + tangentY * sign * stepDistance;
    if (!findSolidCell(grid, cx, cy, radius)) return { x: cx, y: cy };
  }
  return null;
}

function moveWithCollision(grid, x, y, dx, dy, radius) {
  // The y-check is deliberately chained onto the resolved nx (not the
  // original x): testing the exact combined endpoint is what guarantees the
  // position this function returns can never itself land inside solid
  // geometry. Testing y against the original x instead looks more
  // "independent" but is unsound - a diagonal step past a convex corner can
  // pass both single-axis probes (each individually clear) while the actual
  // combined endpoint lands inside the tile, tunnelling through the corner.
  // Chaining avoids that: nx is validated by the x-probe, and if the y-probe
  // (run at nx) is clear too then (nx, ny) - the exact returned point - was
  // just tested directly; if it's blocked, ny falls back to y, leaving the
  // already-validated (nx, y) as the result. Either way the returned point
  // was actually checked, never assembled from two independent partial
  // checks that don't cover the diagonal in between.
  let nx = x + dx;
  const xBlocker = findSolidCell(grid, nx, y, radius);
  if (xBlocker) nx = x;
  let ny = y + dy;
  const yBlocker = findSolidCell(grid, nx, ny, radius);
  if (yBlocker) ny = y;
  if (nx !== x || ny !== y) return { x: nx, y: ny };
  if (dx === 0 || dy === 0) return { x, y };

  // Both pure-axis moves are blocked from the exact same starting point.
  // For genuinely diagonal input this is usually a concave corner wedge,
  // not a real dead end: the circle is resting against the corner point of
  // a wall tile, where the diagonal input drives almost straight into that
  // point, leaving each individual axis with only a sliver of clearance
  // that a full-length step overshoots. A real dead end (boxed in on every
  // side) has no open tangent either, so it still ends up frozen - this
  // only opens an escape where one genuinely exists.
  //
  // Prefer an actual wall tile over the arena boundary as the pivot for the
  // slide: the boundary has no tile corner to compute a tangent from, but a
  // wall tile pinned against the boundary (e.g. hugging the left edge with a
  // wall segment overhead) still has real slide geometry, and the candidate
  // point below is re-validated against both bounds and tiles regardless.
  const tileBlocker = xBlocker && xBlocker.row >= 0
    ? xBlocker
    : yBlocker && yBlocker.row >= 0 ? yBlocker : null;
  const slid = cornerSlide(grid, x, y, dx, dy, radius, tileBlocker);
  if (slid) return slid;
  return { x, y };
}

function hasMovementClearance(grid, x0, y0, x1, y1, radius) {
  const dist = Math.hypot(x1 - x0, y1 - y0);
  const steps = Math.max(1, Math.ceil(dist / (TILE / 4)));
  for (let step = 1; step <= steps; step += 1) {
    const progress = step / steps;
    const sampleX = x0 + (x1 - x0) * progress;
    const sampleY = y0 + (y1 - y0) * progress;
    if (findSolidCell(grid, sampleX, sampleY, radius)) return false;
  }
  return true;
}

// The arena is only 9x19 cells, so a fresh breadth-first route is cheap and
// deterministic. Enemies use direct steering whenever the target is
// unobstructed; this returns only the next open cell when a wall blocks that
// route. It replaces the old anti-softlock wall phasing, which solved
// deadlocks by visibly driving through intact cover.
export function nextPathWaypoint(grid, x, y, targetX, targetY, radius) {
  const startCol = clamp(Math.floor(x / TILE), 0, GRID_COLS - 1);
  const startRow = clamp(Math.floor(y / TILE), 0, GRID_ROWS - 1);
  let targetCol = clamp(Math.floor(targetX / TILE), 0, GRID_COLS - 1);
  let targetRow = clamp(Math.floor(targetY / TILE), 0, GRID_ROWS - 1);
  // A desired point (e.g. a Scout's skirmish anchor, which is placed purely
  // geometrically relative to its target and knows nothing about terrain)
  // can land inside solid ground. When that happens, retarget to the
  // nearest actually-open cell instead. `retargeted` tracks that this
  // happened, because the two cases need different fallback coordinates
  // below - conflating them previously let a still-solid point leak back
  // out to the caller (see the startIndex===targetIndex branch).
  let retargeted = false;
  if (findSolidCell(grid, targetCol * TILE + TILE / 2, targetRow * TILE + TILE / 2, radius)) {
    retargeted = true;
    let bestDistance = Infinity;
    for (let row = 0; row < GRID_ROWS; row += 1) {
      for (let col = 0; col < GRID_COLS; col += 1) {
        const centerX = col * TILE + TILE / 2;
        const centerY = row * TILE + TILE / 2;
        if (findSolidCell(grid, centerX, centerY, radius)) continue;
        const candidateDistance = Math.hypot(centerX - targetX, centerY - targetY);
        if (candidateDistance < bestDistance) {
          bestDistance = candidateDistance;
          targetCol = col;
          targetRow = row;
        }
      }
    }
  }
  const startIndex = startRow * GRID_COLS + startCol;
  const targetIndex = targetRow * GRID_COLS + targetCol;
  if (startIndex === targetIndex) {
    // Already in the target cell. Normally that means "the raw target is
    // close enough to arrive at directly" (returning it as-is keeps
    // movement smooth rather than snapping to a tile centre). But if the
    // target was solid and got retargeted to this very cell, the raw
    // target is still the unreachable point behind the wall - returning it
    // here previously made the mover steer into solid terrain forever,
    // reading as a stuck spin right at the wall face (a real playtest found
    // this exact symptom for Scouts jockeying for a firing slot near a
    // corner). Return the retargeted cell's own centre instead.
    return retargeted
      ? { x: targetCol * TILE + TILE / 2, y: targetRow * TILE + TILE / 2 }
      : { x: targetX, y: targetY };
  }

  const cellCount = GRID_ROWS * GRID_COLS;
  const previous = new Int16Array(cellCount);
  previous.fill(-2);
  previous[startIndex] = -1;
  const queue = new Int16Array(cellCount);
  let head = 0;
  let tail = 0;
  queue[tail] = startIndex;
  tail += 1;
  const directions = [[0, -1], [-1, 0], [1, 0], [0, 1]];

  while (head < tail && previous[targetIndex] === -2) {
    const index = queue[head];
    head += 1;
    const row = Math.floor(index / GRID_COLS);
    const col = index % GRID_COLS;
    for (const [dc, dr] of directions) {
      const nextCol = col + dc;
      const nextRow = row + dr;
      if (nextCol < 0 || nextCol >= GRID_COLS || nextRow < 0 || nextRow >= GRID_ROWS) continue;
      const nextIndex = nextRow * GRID_COLS + nextCol;
      if (previous[nextIndex] !== -2) continue;
      const centerX = nextCol * TILE + TILE / 2;
      const centerY = nextRow * TILE + TILE / 2;
      if (findSolidCell(grid, centerX, centerY, radius)) continue;
      previous[nextIndex] = index;
      queue[tail] = nextIndex;
      tail += 1;
    }
  }

  if (previous[targetIndex] === -2) return null;
  let nextIndex = targetIndex;
  while (previous[nextIndex] !== startIndex && previous[nextIndex] >= 0) {
    nextIndex = previous[nextIndex];
  }
  const nextCol = nextIndex % GRID_COLS;
  const nextRow = Math.floor(nextIndex / GRID_COLS);
  return { x: nextCol * TILE + TILE / 2, y: nextRow * TILE + TILE / 2 };
}

// Tries the straight line toward (targetX, targetY) first, then a fixed,
// deterministic fan of alternate headings, picking the first that actually
// produces movement. This is the sole obstacle-avoidance strategy for
// enemy tanks - simple, cheap, and reproducible.
const AVOIDANCE_OFFSETS_DEG = [0, 25, -25, 50, -50, 80, -80, 110, -110, 140, -140];

function steerToward(grid, x, y, radius, targetX, targetY, speed, dtSec, currentHeading = 0) {
  const desiredAngle = Math.atan2(targetY - y, targetX - x);
  // Cap the step to the remaining distance so a mover converging on a fixed
  // point target (a BFS waypoint's tile centre, most notably) settles onto
  // it instead of perpetually overshooting past it and bouncing back next
  // frame - a real playtest found Scouts doing exactly that (a visible
  // spin/stutter with no net progress) once they'd nearly reached a firing
  // slot right at a corner. A full, unclamped speed*dtSec step is larger
  // than the sub-pixel distance left at that point, and because the
  // overshoot direction is essentially the reverse of the prior frame's,
  // it forms a stable two-point limit cycle instead of arriving. Distant
  // targets (the overwhelming majority of movement) are unaffected, since
  // remaining is far larger than a single step until the final frame or two.
  const remaining = Math.hypot(targetX - x, targetY - y);
  const stepDistance = Math.min(speed * dtSec, remaining);
  for (const offsetDeg of AVOIDANCE_OFFSETS_DEG) {
    const angle = desiredAngle + (offsetDeg * Math.PI) / 180;
    const dx = Math.cos(angle) * stepDistance;
    const dy = Math.sin(angle) * stepDistance;
    const moved = moveWithCollision(grid, x, y, dx, dy, radius);
    if (moved.x !== x || moved.y !== y) {
      // Preserve the established steering/firing orientation whenever the
      // tank moves. Only a completely rejected move retains the old heading
      // below, which removes in-place spinning without changing combat aim.
      return { x: moved.x, y: moved.y, heading: angle, blocked: false };
    }
  }
  // A blocked body has not turned or moved. Retain its prior heading so an
  // unreachable steering target cannot create an in-place spin animation.
  return { x, y, heading: currentHeading, blocked: true };
}

// Nudges a same-type enemy's desired steering point away from other
// same-type enemies within its minimum gap. This runs before steerToward,
// so it is a soft steering bias (drive around each other) rather than a
// hard positional shove like resolveTankCollisions below - it is what stops
// several enemies converging on the same target (most visibly scouts, which
// all independently chase the player with no awareness of each other) from
// stacking into a visible trailing line in the first place. Deliberately
// simple - not flocking/boids, just enough to stop literal clumping. Only
// called for erratic types (see the call site) so it never perturbs the
// heavy/artillery/boss base-seeking pathing the balance tests pin down.
function separationOffset(enemy, allEnemies, typeStats) {
  const minGap = typeStats.radius * 2 + 16;
  let offsetX = 0;
  let offsetY = 0;
  for (const other of allEnemies) {
    if (other === enemy || other.hp <= 0 || other.type !== enemy.type) continue;
    const dx = enemy.x - other.x;
    const dy = enemy.y - other.y;
    const dist = Math.hypot(dx, dy);
    if (dist > 0 && dist < minGap) {
      // Cubic falloff: negligible at the edge of minGap (so most of a
      // chase trajectory is untouched), sharply stronger only once two
      // enemies are nearly on top of each other - an emergency nudge
      // right at the moment they'd otherwise stack, not a constant drift.
      const push = ((minGap - dist) / minGap) ** 3;
      offsetX += (dx / dist) * push;
      offsetY += (dy / dist) * push;
    }
  }
  const strength = 900;
  return { x: offsetX * strength, y: offsetY * strength };
}

// Iterative, terrain-aware tank separation. A single pairwise pass can fix
// A-vs-B and then push B back into C, while unconstrained positional pushes
// can put a tank inside permanent steel. Several cheap passes are fine for
// this game's small entity counts and make the actual guarantee match the
// documented one: live tanks finish outside one another and outside terrain.
function resolveTankCollisions(player, enemies, grid, base) {
  const bodies = [
    { entity: player, radius: PLAYER_STATS.radius, movable: true },
    ...enemies.filter((enemy) => enemy.hp > 0).map((enemy) => ({
      entity: enemy,
      radius: ENEMY_TYPES[enemy.type].radius,
      // A sentry is a fixed emplacement, not a tank. Letting it take part in
      // positional separation meant it could be shoved off its post by driving
      // into it, which contradicts the one thing the mode promises about it.
      movable: !enemy.sentry,
    })),
    // The base is visually a solid structure, so it participates as an
    // immovable body. Previously tanks could route all the way to its exact
    // centre because only tank-vs-tank overlap was resolved. A mode with no
    // base has nothing here to collide with, and adding it anyway put an
    // invisible wall in the middle of otherwise clear ground.
    ...(base ? [{ entity: base, radius: base.radius, movable: false }] : []),
  ];

  function candidate(body, dx, dy) {
    if (!body.movable) return null;
    const x = clamp(body.entity.x + dx, body.radius, WORLD.width - body.radius);
    const y = clamp(body.entity.y + dy, body.radius, WORLD.height - body.radius);
    return findSolidCell(grid, x, y, body.radius) ? null : { x, y };
  }

  for (let pass = 0; pass < 12; pass += 1) {
    let foundOverlap = false;
    for (let i = 0; i < bodies.length; i += 1) {
      for (let j = i + 1; j < bodies.length; j += 1) {
        const a = bodies[i];
        const b = bodies[j];
        const dx = b.entity.x - a.entity.x;
        const dy = b.entity.y - a.entity.y;
        const minDist = a.radius + b.radius;
        const dist = Math.hypot(dx, dy);
        if (dist >= minDist - 1e-6) continue;
        foundOverlap = true;

        let nx = dist > 0 ? dx / dist : 1;
        let ny = dist > 0 ? dy / dist : 0;
        if (dist === 0 && !a.movable && b.movable) {
          nx = -Math.cos(b.entity.heading ?? 0);
          ny = -Math.sin(b.entity.heading ?? 0);
        } else if (dist === 0 && a.movable && !b.movable) {
          nx = Math.cos(a.entity.heading ?? 0);
          ny = Math.sin(a.entity.heading ?? 0);
        }
        const overlap = minDist - dist + 1e-4;

        if (!a.movable || !b.movable) {
          const moved = a.movable
            ? candidate(a, -nx * overlap, -ny * overlap)
            : candidate(b, nx * overlap, ny * overlap);
          if (moved) Object.assign(a.movable ? a.entity : b.entity, moved);
          continue;
        }

        const aHalf = candidate(a, -(nx * overlap) / 2, -(ny * overlap) / 2);
        const bHalf = candidate(b, (nx * overlap) / 2, (ny * overlap) / 2);

        if (aHalf && bHalf) {
          Object.assign(a.entity, aHalf);
          Object.assign(b.entity, bHalf);
          continue;
        }

        // If terrain blocks one body, the other takes the full separation.
        const aFull = aHalf ? candidate(a, -nx * overlap, -ny * overlap) : null;
        const bFull = bHalf ? candidate(b, nx * overlap, ny * overlap) : null;
        if (aFull) Object.assign(a.entity, aFull);
        else if (bFull) Object.assign(b.entity, bFull);
      }
    }
    if (!foundOverlap) break;
  }
}

export function hasLineOfSight(grid, x0, y0, x1, y1) {
  const dist = Math.hypot(x1 - x0, y1 - y0);
  const steps = Math.max(1, Math.ceil(dist / (TILE / 4)));
  for (let i = 1; i < steps; i += 1) {
    const t = i / steps;
    const x = x0 + (x1 - x0) * t;
    const y = y0 + (y1 - y0) * t;
    const col = Math.floor(x / TILE);
    const r = Math.floor(y / TILE);
    if (r < 0 || r >= GRID_ROWS || col < 0 || col >= GRID_COLS) return false;
    const cell = grid[r][col];
    if (cell === "#" || cell === "%" || cell === "^") return false;
  }
  return true;
}

// A Ghost Sapper placement is safe only when no living direct-fire unit is
// close enough to engage the player through an unobstructed firing line.
// Artillery is deliberately excluded: its high arc is already the explicit
// terrain exception, and treating it as omniscient would make scrub cover
// meaningless for this objective.
export function isPlayerDetected(player, enemies, grid) {
  return enemies.some((enemy) => {
    if (enemy.hp <= 0) return false;
    const typeStats = ENEMY_TYPES[enemy.type];
    if (!typeStats || typeStats.arcsWalls) return false;
    const detectionRange = typeStats.target === "player"
      ? typeStats.range
      : typeStats.retaliationRange ?? 0;
    if (detectionRange <= 0 || distance(enemy, player) > detectionRange) return false;
    if (typeStats.retaliationFrontHalfAngleDeg) {
      const playerAngle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
      if (
        Math.abs(normalizeAngle(playerAngle - enemy.heading)) >
        (typeStats.retaliationFrontHalfAngleDeg * Math.PI) / 180
      ) return false;
    }
    return hasLineOfSight(grid, enemy.x, enemy.y, player.x, player.y);
  });
}

// Finds a reachable, readable location for the optional map objectives.
// Generated Sapper markers previously used the first scrub tile in a fixed
// scan order, which put the objective beside enemy spawns on maps whose only
// scrub was at the top edge. Score every valid mid-field cell instead: Sapper
// favours concealed/covered positions, while Relay favours an accessible
// contested point. Explicit authored coordinates are preserved when valid.
export function objectivePositionFor(levelOrId, type, requested = {}) {
  const level = typeof levelOrId === "string" ? levelById(levelOrId) : levelOrId;
  const objective = SECONDARY_OBJECTIVES[type];
  if (!level || !objective || !["relay", "sapper"].includes(type)) {
    return { x: WORLD.width / 2, y: 360 };
  }

  const isValid = (x, y) => {
    if (!Number.isFinite(x) || !Number.isFinite(y)) return false;
    if (findSolidCell(level.grid, x, y, 9)) return false;
    if (distance({ x, y }, level.base) < objective.radius + level.base.radius + 24) return false;
    return nextPathWaypoint(
      level.grid,
      level.playerSpawn.x,
      level.playerSpawn.y,
      x,
      y,
      PLAYER_STATS.radius,
    ) !== null;
  };

  if (isValid(Number(requested.x), Number(requested.y))) {
    return { x: Number(requested.x), y: Number(requested.y) };
  }

  const candidates = [];
  for (let row = 3; row <= GRID_ROWS - 6; row += 1) {
    for (let col = 1; col < GRID_COLS - 1; col += 1) {
      const x = col * TILE + TILE / 2;
      const y = row * TILE + TILE / 2;
      if (!isValid(x, y)) continue;

      const terrain = level.grid[row][col];
      const distanceFromPlayer = distance({ x, y }, level.playerSpawn);
      const distanceFromClosestSpawn = Math.min(...level.spawnPoints.map((spawn) => distance({ x, y }, spawn)));
      const blockedSpawnLines = level.spawnPoints.reduce(
        (count, spawn) => count + (hasLineOfSight(level.grid, spawn.x, spawn.y, x, y) ? 0 : 1),
        0,
      );
      let neighbouringCover = 0;
      for (let rowOffset = -1; rowOffset <= 1; rowOffset += 1) {
        for (let colOffset = -1; colOffset <= 1; colOffset += 1) {
          if (rowOffset === 0 && colOffset === 0) continue;
          if ("#%^".includes(level.grid[row + rowOffset]?.[col + colOffset] ?? "")) neighbouringCover += 1;
        }
      }
      const score = type === "sapper"
        ? blockedSpawnLines * 180 + neighbouringCover * 34 + (terrain === "^" ? 150 : 0) +
          Math.min(240, distanceFromClosestSpawn) - Math.abs(distanceFromPlayer - 230) * 0.45 -
          Math.abs(y - 360) * 0.45
        : neighbouringCover * 18 + Math.min(180, distanceFromClosestSpawn) * 0.35 -
          Math.abs(distanceFromPlayer - 190) * 0.35 - Math.abs(y - 360) * 0.2;
      candidates.push({ x, y, score });
    }
  }

  candidates.sort((a, b) => b.score - a.score || a.y - b.y || a.x - b.x);
  return candidates[0]
    ? { x: candidates[0].x, y: candidates[0].y }
    : {
        x: clamp(Number(requested.x) || WORLD.width - level.base.x, TILE / 2, WORLD.width - TILE / 2),
        y: clamp(Number(requested.y) || 360, TILE / 2, WORLD.height - TILE / 2),
      };
}

// Drop mines just behind the tank so the result matches the player's driving
// direction and remains visible after deployment. A deterministic rearward
// fan finds the nearest terrain-safe alternative near walls and boundaries.
export function minePlacementFor(player, grid, mines = [], requiredZone = null) {
  const mineRadius = 9;
  const offset = PLAYER_STATS.radius + mineRadius + 7;
  const rear = (player.heading ?? -Math.PI / 2) + Math.PI;
  const angleOffsets = [0, Math.PI / 4, -Math.PI / 4, Math.PI / 2, -Math.PI / 2, Math.PI];
  const isValid = (candidate) => {
    if (findSolidCell(grid, candidate.x, candidate.y, mineRadius)) return false;
    if (mines.some((mine) => distance(mine, candidate) < TACTICAL_RULES.mineTriggerRadius * 1.5)) return false;
    if (requiredZone && distance(candidate, requiredZone) > requiredZone.radius + mineRadius) return false;
    return true;
  };
  for (const angleOffset of angleOffsets) {
    const angle = rear + angleOffset;
    const candidate = {
      x: player.x + Math.cos(angle) * offset,
      y: player.y + Math.sin(angle) * offset,
    };
    if (isValid(candidate)) return candidate;
  }
  const centre = { x: player.x, y: player.y };
  if (requiredZone && isValid(centre)) return centre;
  return null;
}

export function findAutoFireTarget(shooter, candidates, grid, range, visionAngleDeg) {
  const tolerance = (visionAngleDeg * Math.PI) / 180;
  let best = null;
  let bestDistance = Infinity;
  for (const candidate of candidates) {
    if (candidate.hp <= 0) continue;
    const dx = candidate.x - shooter.x;
    const dy = candidate.y - shooter.y;
    const dist = Math.hypot(dx, dy);
    if (dist > range) continue;
    const angleTo = Math.atan2(dy, dx);
    if (Math.abs(normalizeAngle(angleTo - shooter.heading)) > tolerance) continue;
    if (!hasLineOfSight(grid, shooter.x, shooter.y, candidate.x, candidate.y)) continue;
    if (dist < bestDistance) {
      bestDistance = dist;
      best = candidate;
    }
  }
  return best;
}

export function isBossFrontArmorHit(enemy, impact) {
  const halfAngleDeg = ENEMY_TYPES[enemy.type]?.frontArmorHalfAngleDeg;
  if (!halfAngleDeg) return false;
  const impactAngle = Math.atan2(impact.y - enemy.y, impact.x - enemy.x);
  return Math.abs(normalizeAngle(impactAngle - enemy.heading)) <= (halfAngleDeg * Math.PI) / 180;
}

function createBullet(id, owner, x, y, angle, statsSource, ammoMode = null, tacticalSource = null) {
  const ammo = ammoMode ? AMMO_TYPES[ammoMode] : null;
  return {
    id,
    owner,
    originX: x,
    originY: y,
    x,
    y,
    vx: Math.cos(angle) * (ammo?.bulletSpeed ?? statsSource.bulletSpeed),
    vy: Math.sin(angle) * (ammo?.bulletSpeed ?? statsSource.bulletSpeed),
    radius: ammo?.bulletRadius ?? statsSource.bulletRadius,
    damage: ammo?.damage ?? statsSource.damage,
    ammoMode,
    blastRadius: (ammo?.blastRadius ?? 0) + (ammoMode === "he" ? tacticalSource?.heBlastBonus ?? 0 : 0),
    // Only the player's HE round opens brick. Enemy direct fire and AP must
    // stop at the visible cover without silently removing it for the next
    // shell, otherwise repeated fire reads as shooting through a wall.
    destroysBrick: ammo?.destroysBrick ?? false,
    arcsWalls: false,
  };
}

function createArcShell(id, owner, origin, target, statsSource) {
  const dist = Math.max(1, Math.hypot(target.x - origin.x, target.y - origin.y));
  const totalTravelMs = (dist / statsSource.bulletSpeed) * 1000;
  return {
    id,
    owner,
    arcsWalls: true,
    originX: origin.x,
    originY: origin.y,
    targetX: target.x,
    targetY: target.y,
    x: origin.x,
    y: origin.y,
    travelMs: 0,
    totalTravelMs,
    radius: statsSource.bulletRadius,
    damage: statsSource.damage,
    blastRadius: statsSource.blastRadius,
  };
}

function createEnemy(id, type, spawnPoint, drop, ace = null) {
  const typeStats = ENEMY_TYPES[type];
  const trait = ace ? ACE_TRAITS[ace.trait] : null;
  return {
    id,
    type,
    x: spawnPoint.x,
    y: spawnPoint.y,
    heading: Math.PI / 2,
    turretHeading: Math.PI / 2,
    hp: typeStats.maxHp + (trait?.hpBonus ?? 0),
    maxHp: typeStats.maxHp + (trait?.hpBonus ?? 0),
    speedMultiplier: trait?.speedMultiplier ?? 1,
    fireCooldownMultiplier: trait?.fireCooldownMultiplier ?? 1,
    ace: ace ? { name: ace.name, trait: trait?.id ?? ace.trait } : null,
    fireCooldownMs: typeStats.arcsWalls
      ? typeStats.telegraphMs
      : typeStats.fireCooldownMs * 0.5 * (trait?.fireCooldownMultiplier ?? 1),
    drop: drop ?? null,
    aiState: {
      jitterAngle: 0,
      jitterTimerMs: 0,
      separationX: 0,
      separationY: 0,
      stuckMs: 0,
      checkTimerMs: STUCK_CHECK_WINDOW_MS,
      checkX: spawnPoint.x,
      checkY: spawnPoint.y,
      holding: false,
      deployProgressMs: 0,
      deployed: false,
      retreatMs: 0,
      windingUp: false,
      aimProgress: 0,
      targetingPlayer: false,
      phased: false,
    },
  };
}

// Movement diagnostics retained in state for deterministic tests and future
// telemetry. Routing, rather than collision bypass, resolves blocked paths.
const STUCK_CHECK_WINDOW_MS = 400;
const STUCK_PROGRESS_PX = 16;
const STUCK_RETREAT_AFTER_MS = 1_600;

// mulberry32 - small, fast, fully deterministic PRNG. Advancing it is an
// explicit state transition (returns the next seed alongside the value) so
// callers stay pure.
function nextRandom(seed) {
  let t = (seed + 0x6d2b79f5) | 0;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  const value = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  return { value, seed: t };
}

function hashSeed(text) {
  let hash = 0;
  for (let i = 0; i < text.length; i += 1) {
    hash = (Math.imul(31, hash) + text.charCodeAt(i)) | 0;
  }
  return hash;
}

export function createSpawnPlan(levelOrId) {
  const level = typeof levelOrId === "string" ? levelById(levelOrId) : levelOrId;
  return level.waveEntries.map((entry) => ({
    ...entry,
    ace: entry.ace ? { ...entry.ace } : undefined,
  }));
}

export function createEndlessWave(levelOrId, wave, startElapsedMs = 0) {
  const level = typeof levelOrId === "string" ? levelById(levelOrId) : levelOrId;
  const count = ENDLESS_RULES.startingEnemies + Math.min(12, Math.max(0, wave - 1));
  const entries = [];
  for (let index = 0; index < count; index += 1) {
    let type = "scout";
    if (wave % ENDLESS_RULES.bossEvery === 0 && index === count - 1) type = "boss";
    else if ((index + wave) % 5 === 0) type = "artillery";
    else if ((index + wave) % 3 === 0) type = "heavy";
    entries.push({
      delayMs: startElapsedMs + ENDLESS_RULES.interWaveDelayMs + index * Math.max(350, 1_100 - wave * 45),
      type,
      spawnPointIndex: (index + wave) % level.spawnPoints.length,
    });
  }
  return entries;
}

function createSecondaryObjective(definition, level) {
  if (!definition || !SECONDARY_OBJECTIVES[definition.type]) return null;
  if (definition.type === "relay" || definition.type === "sapper") {
    const objective = SECONDARY_OBJECTIVES[definition.type];
    const position = objectivePositionFor(level, definition.type, definition);
    return {
      type: definition.type,
      label: objective.label,
      x: position.x,
      y: position.y,
      radius: objective.radius,
      ...(definition.type === "relay"
        ? { requiredMs: objective.requiredMs, progressMs: 0 }
        : { inZone: false, spotted: false }),
      completed: false,
    };
  }
  return {
    type: "ace-hunt",
    label: SECONDARY_OBJECTIVES["ace-hunt"].label,
    completed: false,
  };
}

// Sentries are built at level start and again at every stage change. That was
// written out twice, so a change to what a sentry is could land in one and not
// the other. One builder now.
function makeSentry(id, position, rules, level) {
  const gun = createEnemy(id, "artillery", position);
  gun.sentry = true;
  gun.aiState.deployed = true;
  gun.aiState.holding = true;
  gun.fireCooldownMs = rules.openingMs;
  // An emplacement is not a field gun that happens to sit still. At artillery's
  // 2 HP a sentry died to two rounds of the player's auto-fire, so driving past
  // cleared it for nothing and the mode's premise - stay out of their sight -
  // cost nothing to ignore. Tough enough that a drive-by no longer erases one,
  // while the player keeps their gun and their own survivability is untouched.
  if (level.sentryHp) {
    gun.maxHp = level.sentryHp;
    gun.hp = level.sentryHp;
  }
  return gun;
}

export function createLevelState(levelId, options = {}) {
  options = {};
  const level = levelById(levelId);
  const stage = stageOf(level, 0);
  const openingRules = sentryRulesFor(level, 0);
  const sentries = (stage.sentries ?? []).map((position, index) => makeSentry(100 + index, position, openingRules, level));
  const doctrine = DOCTRINES[options.doctrine] ?? null;
  const baseMaxHp = level.base.maxHp + (doctrine?.baseHpBonus ?? 0);
  const spawnPlan = options.endless
    ? createEndlessWave(level, 1, 0)
    : createSpawnPlan(level);
  // A relay needs a real artillery threat to jam. Replace one ordinary
  // attacker, never add a hidden extra enemy or change a boss encounter.
  if (options.secondaryObjective?.type === "relay" && !spawnPlan.some(e => e.type === "artillery")) {
    const candidates = spawnPlan.map((entry, index) => ({ entry, index }))
      .filter(({ entry, index }) => index >= Math.floor(spawnPlan.length / 2)
        && entry.type !== "boss" && entry.delayMs > 0);
    const index = candidates[0]?.index ?? -1;
    if (index >= 0) spawnPlan[index] = { ...spawnPlan[index], type: "artillery" };
  }
  if (options.ace && spawnPlan.length > 0) {
    const aceIndex = clamp(
      Math.trunc(options.ace.spawnPlanIndex ?? spawnPlan.length - 1),
      0,
      spawnPlan.length - 1,
    );
    spawnPlan[aceIndex] = {
      ...spawnPlan[aceIndex],
      ace: { name: options.ace.name, trait: options.ace.trait },
    };
  }
  return {
    levelId: level.id,
    phase: "ready",
    elapsedMs: 0,
    // Which board of a staged level is being played. Zero on every level that
    // has only one.
    stage: 0,
    grid: [...stage.grid],
    player: {
      x: stage.playerSpawn.x,
      y: stage.playerSpawn.y,
      heading: -Math.PI / 2,
      hp: PLAYER_STATS.maxHp,
      maxHp: PLAYER_STATS.maxHp,
      fireCooldownMs: 0,
      gunnerCooldownMs: 0,
      doctrine: doctrine?.id ?? null,
      speedMultiplier: doctrine?.speedMultiplier ?? 1,
      braceDelayMs: TACTICAL_RULES.braceDelayMs * (doctrine?.braceDelayMultiplier ?? 1),
      bracedRangeBonus: doctrine?.bracedRangeBonus ?? 0,
      heBlastBonus: doctrine?.heBlastBonus ?? 0,
      ammoMode: "ap",
      terrain: terrainAt(stage.grid, stage.playerSpawn.x, stage.playerSpawn.y),
      stationaryMs: 0,
      braced: false,
      minesRemaining: (level.mineCount ?? 1) + (doctrine?.mineBonus ?? 0),
      // Counts down to the next mine on levels that resupply them; ignored
      // everywhere else.
      mineResupplyMs: level.mineResupplyMs ?? 0,
      powerups: { spread: 0, shield: 0 },
    },
    enemies: sentries,
    bullets: [],
    mines: [],
    powerupPickups: [],
    base: { x: level.base.x, y: level.base.y, radius: level.base.radius, hp: baseMaxHp, maxHp: baseMaxHp },
    doctrine: doctrine?.id ?? null,
    secondaryObjective: createSecondaryObjective(options.secondaryObjective, level),
    battleAdvantage: null,
    escort: level.escortRoute ? { checkpoint: 0, status: "moving" } : null,
    lastDamage: null,
    secretCache: options.secretCache
      ? {
          id: String(options.secretCache.id ?? "field-cache"),
          x: clamp(Number(options.secretCache.x) || TILE / 2, TILE / 2, WORLD.width - TILE / 2),
          y: clamp(Number(options.secretCache.y) || TILE / 2, TILE / 2, WORLD.height - TILE / 2),
          radius: clamp(Number(options.secretCache.radius) || 11, 6, 20),
          revealRadius: clamp(Number(options.secretCache.revealRadius) || 125, 60, 220),
          hint: typeof options.secretCache.hint === "string" ? options.secretCache.hint.slice(0, 180) : "",
          collected: false,
        }
      : null,
    endless: Boolean(options.endless),
    endlessWave: options.endless ? 1 : 0,
    spawnPlan,
    nextEntityId: 100 + sentries.length,
    rngSeed: hashSeed(level.id),
    stats: { enemiesDefeated: 0, shotsFired: 0, shotsHit: 0 },
    events: [],
    result: null,
  };
}

export function startLevel(state) {
  if (state.phase !== "ready") return state;
  return { ...state, phase: "playing" };
}

export function stepLevel(state, input, dtMs) {
  if (state.phase !== "playing") return state;
  const dtSec = dtMs / 1000;
  const events = [];
  let grid = state.grid;
  let rngSeed = state.rngSeed;
  let nextEntityId = state.nextEntityId;
  let stats = { ...state.stats };
  const level = levelById(state.levelId);
  let stage = state.stage ?? 0;
  const currentStage = stageOf(level, stage);

  const moveVector = normalizeInputVector(input ?? { x: 0, y: 0 });
  const directionalInput = Math.hypot(moveVector.x, moveVector.y) > 0.08;
  const aimingOnly = Boolean(input?.aimOnly) && directionalInput;
  const moving = directionalInput && !aimingOnly;
  const player = { ...state.player, powerups: { ...state.player.powerups } };
  const previousPlayerTerrain = player.terrain ?? terrainAt(grid, player.x, player.y);
  if (AMMO_TYPES[input?.ammoMode]) player.ammoMode = input.ammoMode;
  player.stationaryMs = moving ? 0 : Math.min(
    player.braceDelayMs ?? TACTICAL_RULES.braceDelayMs,
    (player.stationaryMs ?? 0) + dtMs,
  );
  player.braced = player.stationaryMs >= (player.braceDelayMs ?? TACTICAL_RULES.braceDelayMs);
  const playerSpeed = PLAYER_STATS.speed *
    (player.speedMultiplier ?? 1) *
    terrainSpeedMultiplier(grid, player.x, player.y);
  const moved = moveWithCollision(
    grid,
    player.x,
    player.y,
    aimingOnly ? 0 : moveVector.x * playerSpeed * dtSec,
    aimingOnly ? 0 : moveVector.y * playerSpeed * dtSec,
    PLAYER_STATS.radius,
  );
  player.x = moved.x;
  player.y = moved.y;
  player.terrain = terrainAt(grid, player.x, player.y);
  if (moving && player.terrain !== previousPlayerTerrain) {
    if (player.terrain === "~") {
      events.push({ type: EVENTS.PLAYER_ENTERED_MUD, x: player.x, y: player.y });
    } else if (player.terrain === "^") {
      events.push({ type: EVENTS.PLAYER_ENTERED_SCRUB, x: player.x, y: player.y });
    }
  }
  if (moving || aimingOnly) player.heading = Math.atan2(moveVector.y, moveVector.x);
  player.powerups.spread = Math.max(0, player.powerups.spread - dtMs);
  player.powerups.shield = Math.max(0, player.powerups.shield - dtMs);
  player.fireCooldownMs = Math.max(0, player.fireCooldownMs - dtMs);
  const nextManualCooldownMs = (player.gunnerCooldownMs ?? 0) - dtMs;
  // Fixed 60 Hz steps can leave a tiny positive floating-point remainder at
  // the exact 0.7 s boundary. Snap sub-millisecond residue to zero so the
  // visible FIRE button and the simulation's input gate become ready together.
  player.gunnerCooldownMs = nextManualCooldownMs <= 0.001 ? 0 : nextManualCooldownMs;

  let enemies = state.enemies.map((enemy) => ({ ...enemy, aiState: { ...enemy.aiState } }));
  let bullets = state.bullets.map((bullet) => ({ ...bullet }));
  let mines = (state.mines ?? []).map((mine) => ({ ...mine }));
  let pickups = state.powerupPickups.map((pickup) => ({ ...pickup }));
  let base = { ...state.base };
  let escort = state.escort ? { ...state.escort } : null;
  let battleAdvantage = state.battleAdvantage
    ? { ...state.battleAdvantage, remainingMs: Math.max(0, state.battleAdvantage.remainingMs - dtMs) }
    : null;
  if (escort && escort.checkpoint < level.escortRoute.length) {
    const destination = level.escortRoute[escort.checkpoint];
    const threatened = enemies.some(e => e.hp > 0 && distance(e, base) < 115);
    escort.status = threatened ? "clear-road" : distance(player, base) > 180 ? "regroup" : "moving";
    if (escort.status === "moving") {
      const dx = destination.x - base.x, dy = destination.y - base.y;
      const length = Math.hypot(dx, dy);
      const travel = Math.min(length, level.escortSpeed * dtSec);
      const movedBase = moveWithCollision(grid, base.x, base.y,
        dx / (length || 1) * travel, dy / (length || 1) * travel, base.radius);
      base.x = movedBase.x;
      base.y = movedBase.y;
      if (distance(base, destination) <= 1) {
        escort.checkpoint += 1;
        events.push({ type: EVENTS.CONVOY_CHECKPOINT, checkpoint: escort.checkpoint, x: base.x, y: base.y });
      }
    }
  }
  let secondaryObjective = state.secondaryObjective ? { ...state.secondaryObjective } : null;
  let secretCache = state.secretCache ? { ...state.secretCache } : null;

  if (
    secretCache &&
    !secretCache.collected &&
    distance(player, secretCache) <= PLAYER_STATS.radius + secretCache.radius
  ) {
    secretCache.collected = true;
    events.push({
      type: EVENTS.SECRET_CACHE_COLLECTED,
      id: secretCache.id,
      x: secretCache.x,
      y: secretCache.y,
    });
  }

  if (secondaryObjective?.type === "relay" && !secondaryObjective.completed) {
    const insideRelay = distance(player, secondaryObjective) <= secondaryObjective.radius + PLAYER_STATS.radius;
    secondaryObjective.progressMs = insideRelay
      ? Math.min(secondaryObjective.requiredMs, secondaryObjective.progressMs + dtMs)
      : Math.max(0, secondaryObjective.progressMs - dtMs * 0.35);
    if (secondaryObjective.progressMs >= secondaryObjective.requiredMs) {
      secondaryObjective.completed = true;
      events.push({
        type: EVENTS.OBJECTIVE_COMPLETED,
        objectiveType: secondaryObjective.type,
        x: secondaryObjective.x,
        y: secondaryObjective.y,
      });
    }
  }

  if (secondaryObjective?.type === "sapper" && !secondaryObjective.completed) {
    secondaryObjective.inZone =
      distance(player, secondaryObjective) <= secondaryObjective.radius + PLAYER_STATS.radius;
    secondaryObjective.spotted = isPlayerDetected(player, enemies, grid);
  }

  // Levels that live on mines hand them back on a timer, up to a small
  // reserve. Without it a mines-only mission is over the moment the last
  // one is spent, and the answer to a bad placement is to restart rather
  // than to adapt.
  if (level.mineResupplyMs && player.minesRemaining < (level.mineReserve ?? 4)) {
    player.mineResupplyMs = (player.mineResupplyMs ?? level.mineResupplyMs) - dtMs;
    if (player.mineResupplyMs <= 0) {
      player.minesRemaining += 1;
      player.mineResupplyMs = level.mineResupplyMs;
    }
  } else if (level.mineResupplyMs) {
    player.mineResupplyMs = level.mineResupplyMs;
  }

  if (input?.deployMine && player.minesRemaining > 0) {
    const requiredMineZone = secondaryObjective?.type === "sapper" &&
      !secondaryObjective.completed && secondaryObjective.inZone
      ? secondaryObjective
      : null;
    const placement = minePlacementFor(player, grid, mines, requiredMineZone);
    if (placement) {
      const mine = { id: nextEntityId, ...placement, radius: 9 };
      mines.push(mine);
      nextEntityId += 1;
      player.minesRemaining -= 1;
      events.push({ type: EVENTS.MINE_DEPLOYED, x: mine.x, y: mine.y });
      if (
        secondaryObjective?.type === "sapper" &&
        !secondaryObjective.completed &&
        distance(mine, secondaryObjective) <= secondaryObjective.radius + mine.radius &&
        !secondaryObjective.spotted
      ) {
        secondaryObjective.completed = true;
        events.push({
          type: EVENTS.OBJECTIVE_COMPLETED,
          objectiveType: secondaryObjective.type,
          x: mine.x,
          y: mine.y,
        });
      }
    }
  }

  // Manual fire is an optional direct input: it uses the selected real
  // ammunition and the same projectile/wall/armour path as auto-fire, but
  // can be fired down the current heading without a target lock.
  let firedManualShot = false;
  if (input?.manualFire && !level.minesOnly && player.gunnerCooldownMs <= 0) {
    bullets.push(createBullet(
      nextEntityId,
      "player",
      player.x,
      player.y,
      player.heading,
      PLAYER_STATS,
      player.ammoMode,
      player,
    ));
    events.push({
      type: EVENTS.PLAYER_FIRED,
      x: player.x,
      y: player.y,
      angle: player.heading,
      ammoMode: player.ammoMode,
      braced: player.braced,
      manual: true,
    });
    nextEntityId += 1;
    player.gunnerCooldownMs = GUNNER_STATS.cooldownMs;
    player.fireCooldownMs = Math.max(player.fireCooldownMs, PLAYER_STATS.fireCooldownMs);
    stats.shotsFired += 1;
    firedManualShot = true;
  }

  // Player auto-fire remains the default and only fires when a target is in
  // the facing cone, range, and line of sight.
  // A mines-only level has no gun at all: the whole mission is what you
  // buried before the wave moved, so auto-fire is off as well as the
  // trigger. Half a rule - a dead FIRE button but a turret still shooting
  // by itself - would be worse than either.
  // A stealth mode cannot leave auto-fire on. Measured: standing still in a
  // sentry's line, never touching the trigger, destroys it in about two
  // seconds. So the shortest route through the maze also clears the maze,
  // nobody needs to read a patrol, and "no kills" is untrue by default.
  // Manual fire stays, so HE still opens a route - the player chooses to shoot.
  if (!firedManualShot && !level.minesOnly && level.autoFire !== false && !input?.aimOnly && player.fireCooldownMs <= 0) {
    const playerRange = PLAYER_STATS.range +
      (player.braced ? TACTICAL_RULES.bracedRangeBonus + (player.bracedRangeBonus ?? 0) : 0);
    const playerVision = PLAYER_STATS.visionAngleDeg + (player.braced ? TACTICAL_RULES.bracedVisionBonusDeg : 0);
    const target = findAutoFireTarget(player, enemies, grid, playerRange, playerVision);
    if (target) {
      const spreadActive = player.powerups.spread > 0;
      const offsets = spreadActive ? [-0.18, 0, 0.18] : [0];
      for (const offset of offsets) {
        bullets.push(createBullet(
          nextEntityId,
          "player",
          player.x,
          player.y,
          player.heading + offset,
          PLAYER_STATS,
          player.ammoMode,
          player,
        ));
        events.push({
          type: EVENTS.PLAYER_FIRED,
          x: player.x,
          y: player.y,
          angle: player.heading + offset,
          ammoMode: player.ammoMode,
          braced: player.braced,
        });
        nextEntityId += 1;
      }
      player.fireCooldownMs = PLAYER_STATS.fireCooldownMs *
        (AMMO_TYPES[player.ammoMode]?.cooldownMultiplier ?? 1) *
        (player.braced ? TACTICAL_RULES.bracedCooldownMultiplier : 1);
      stats.shotsFired += offsets.length;
    }
  }

  // Enemy AI: collision-safe routing, type-specific movement, and fire.
  for (const enemy of enemies) {
    if (enemy.hp <= 0) continue;
    if (battleAdvantage?.type === "relay" && battleAdvantage.remainingMs > 0 && enemy.type === "artillery") {
      enemy.fireCooldownMs = Math.max(enemy.fireCooldownMs, battleAdvantage.remainingMs + dtMs);
    }
    const typeStats = ENEMY_TYPES[enemy.type];
    if (enemy.sentry) {
      // A sentry never moves and never chases. It watches its arc, and it
      // only shoots at what it can actually see - which makes cover, not
      // speed, the thing that keeps you alive. Its numbers come from the
      // stage, so later sections are genuinely harder rather than longer.
      const rules = sentryRulesFor(level, stage);
      const exposed = distance(enemy, player) <= rules.watchRange
        && hasLineOfSight(grid, enemy.x, enemy.y, player.x, player.y);
      enemy.turretHeading = Math.atan2(player.y - enemy.y, player.x - enemy.x);
      enemy.aiState.holding = true;
      enemy.aiState.deployed = true;
      if (!exposed) {
        // Breaking line of sight resets the shot it was lining up. Slipping
        // behind a wall is the answer, and it has to work immediately or the
        // maze is decoration.
        enemy.fireCooldownMs = Math.max(enemy.fireCooldownMs, rules.reacquireMs);
        enemy.aiState.windingUp = false;
        enemy.aiState.aimProgress = 0;
        continue;
      }
      enemy.fireCooldownMs = Math.max(0, enemy.fireCooldownMs - dtMs);
      enemy.aiState.windingUp = enemy.fireCooldownMs > 0 && enemy.fireCooldownMs <= typeStats.telegraphMs;
      enemy.aiState.aimProgress = enemy.aiState.windingUp
        ? 1 - enemy.fireCooldownMs / typeStats.telegraphMs
        : 0;
      if (enemy.fireCooldownMs <= 0) {
        const shell = createArcShell(nextEntityId++, "enemy", enemy, player, typeStats);
        bullets.push(shell);
        events.push({ type: EVENTS.ENEMY_FIRED, x: enemy.x, y: enemy.y,
          angle: enemy.turretHeading, enemyType: "artillery", target: "player" });
        enemy.fireCooldownMs = rules.reloadMs;
      }
      continue;
    }
    enemy.aiState.retreatMs = Math.max(0, (enemy.aiState.retreatMs ?? 0) - dtMs);
    const playerInsideScoutLeash = player.y < base.y - (typeStats.pursuitLeashFromBase ?? 0);
    const targetEntity = typeStats.target === "player" && playerInsideScoutLeash ? player : base;
    const targetDistance = distance(enemy, targetEntity);
    const skirmishingPlayer = Boolean(typeStats.preferredRange) && targetEntity === player;
    const retreating = skirmishingPlayer &&
      (enemy.aiState.retreatMs > 0 || targetDistance < typeStats.retreatRange);
    let desiredX = targetEntity.x;
    let desiredY = targetEntity.y;
    let scoutAnchorDistance = Infinity;

    if (retreating) {
      const awayAngle = Math.atan2(enemy.y - targetEntity.y, enemy.x - targetEntity.x);
      desiredX = enemy.x + Math.cos(awayAngle) * 100;
      desiredY = enemy.y + Math.sin(awayAngle) * 100;
    } else if (skirmishingPlayer) {
      enemy.aiState.jitterTimerMs -= dtMs;
      if (enemy.aiState.jitterTimerMs <= 0) {
        const random = nextRandom(rngSeed);
        rngSeed = random.seed;
        enemy.aiState.jitterAngle = (random.value - 0.5) * ((18 * Math.PI) / 180);
        enemy.aiState.jitterTimerMs = 500;
        // Recomputed on the same cadence as jitterAngle rather than every
        // frame (see separationOffset for why it exists at all). A real
        // playtest found scouts stuttering/spinning in place near corners:
        // desiredX/Y here doubles as the BFS route goal a few lines down
        // when a wall blocks the direct line, and a per-frame separation
        // recompute made that goal drift by a sub-pixel amount every tick.
        // BFS re-evaluates the whole route each call, so that constant
        // drift could flip which side of a corner looked shorter from one
        // frame to the next - a visible spin with no net progress. Holding
        // the nudge fixed between jitter ticks removes that high-frequency
        // noise source while keeping the anti-stacking behaviour intact.
        const separation = separationOffset(enemy, enemies, typeStats);
        enemy.aiState.separationX = separation.x;
        enemy.aiState.separationY = separation.y;
      }
      // Scouts occupy one of three front/flank firing positions instead of
      // homing into the player's rear. Slots make simultaneous Scouts read
      // as a skirmish line rather than a stacked red tail.
      const slot = (enemy.id % 3) - 1;
      const anchorAngle = -Math.PI / 2 + slot * 0.82 + enemy.aiState.jitterAngle;
      desiredX = targetEntity.x + Math.cos(anchorAngle) * typeStats.preferredRange;
      desiredY = targetEntity.y + Math.sin(anchorAngle) * typeStats.preferredRange;
      desiredX += enemy.aiState.separationX ?? 0;
      desiredY += enemy.aiState.separationY ?? 0;
      scoutAnchorDistance = Math.hypot(desiredX - enemy.x, desiredY - enemy.y);
    } else if (typeStats.erratic) {
      enemy.aiState.jitterTimerMs -= dtMs;
      if (enemy.aiState.jitterTimerMs <= 0) {
        const r1 = nextRandom(rngSeed);
        rngSeed = r1.seed;
        const r2 = nextRandom(rngSeed);
        rngSeed = r2.seed;
        enemy.aiState.jitterAngle = (r1.value - 0.5) * 2 * ((70 * Math.PI) / 180);
        enemy.aiState.jitterTimerMs = 300 + r2.value * 400;
        // Same throttling as the skirmish branch above and for the same
        // reason: keep the separation nudge from drifting the BFS route
        // goal every single frame near a corner.
        const separation = separationOffset(enemy, enemies, typeStats);
        enemy.aiState.separationX = separation.x;
        enemy.aiState.separationY = separation.y;
      }
      const baseAngle = Math.atan2(targetEntity.y - enemy.y, targetEntity.x - enemy.x);
      const jitteredAngle = baseAngle + enemy.aiState.jitterAngle;
      desiredX = enemy.x + Math.cos(jitteredAngle) * 100;
      desiredY = enemy.y + Math.sin(jitteredAngle) * 100;
      desiredX += enemy.aiState.separationX ?? 0;
      desiredY += enemy.aiState.separationY ?? 0;
    }

    // Any type with a standoff stops advancing once its target is inside it.
    // Only the types that deploy (artillery) also wind up from there.
    // Applies to whatever the unit is actually attacking, and only when that
    // is not a player it is skirmishing. A Scout that has lost its player
    // falls back to the base and needs the standoff; a Scout still working
    // a player must keep its preferred-range dance instead, or it freezes
    // in front of the base and walls off everything advancing behind it.
    const holdingAtStandoff = Boolean(typeStats.standoffRange)
      && !skirmishingPlayer
      && targetDistance <= typeStats.standoffRange
      // A standoff is a firing position, not just a distance - and "can it
      // shoot from here" has to be asked with the shell's own geometry.
      // hasLineOfSight samples a thin line; a shell is a disc with a radius,
      // so sight read clear while every round clipped the corner: 46 shots in
      // 60s, all 46 stopped by the same brick, base untouched, tank convinced
      // it was in position. This runs the exact trace the shell runs.
      // Artillery is exempt because arcing over cover is its whole point.
      && (typeStats.arcsWalls
        || !traceProjectileBlocker(grid, enemy.x, enemy.y,
          targetEntity.x, targetEntity.y, typeStats.bulletRadius));
    const scoutHolding = skirmishingPlayer && !retreating && scoutAnchorDistance <= 14;
    const holding = holdingAtStandoff || scoutHolding;
    enemy.aiState.holding = holding;

    if (holding) {
      enemy.heading = Math.atan2(targetEntity.y - enemy.y, targetEntity.x - enemy.x);
      enemy.aiState.stuckMs = 0;
      enemy.aiState.checkX = enemy.x;
      enemy.aiState.checkY = enemy.y;
      enemy.aiState.phased = false;
      if (holdingAtStandoff && typeStats.deployMs) {
        enemy.aiState.deployProgressMs = Math.min(
          typeStats.deployMs,
          (enemy.aiState.deployProgressMs ?? 0) + dtMs,
        );
        enemy.aiState.deployed = enemy.aiState.deployProgressMs >= typeStats.deployMs;
      }
    } else {
      if (!hasMovementClearance(grid, enemy.x, enemy.y, desiredX, desiredY, typeStats.radius)) {
        const routeGoalX = skirmishingPlayer ? desiredX : targetEntity.x;
        const routeGoalY = skirmishingPlayer ? desiredY : targetEntity.y;
        const waypoint = nextPathWaypoint(
          grid,
          enemy.x,
          enemy.y,
          routeGoalX,
          routeGoalY,
          typeStats.radius,
        );
        if (waypoint) {
          desiredX = waypoint.x;
          desiredY = waypoint.y;
        }
      }
      const terrainSpeed = typeStats.speed *
        (enemy.speedMultiplier ?? 1) *
        terrainSpeedMultiplier(grid, enemy.x, enemy.y);
      const steerResult = steerToward(
        grid,
        enemy.x,
        enemy.y,
        typeStats.radius,
        desiredX,
        desiredY,
        terrainSpeed,
        dtSec,
        enemy.heading,
      );
      enemy.x = steerResult.x;
      enemy.y = steerResult.y;
      enemy.heading = steerResult.heading;
      enemy.aiState.phased = false;
    }

    if (!holding) {
      enemy.aiState.deployProgressMs = 0;
      enemy.aiState.deployed = false;
    }

    if (!holding) {
      enemy.aiState.checkTimerMs -= dtMs;
      if (enemy.aiState.checkTimerMs <= 0) {
        const progressed = Math.hypot(enemy.x - enemy.aiState.checkX, enemy.y - enemy.aiState.checkY);
        const expectedProgress = typeStats.speed * (enemy.speedMultiplier ?? 1) * (STUCK_CHECK_WINDOW_MS / 1000);
        const progressThreshold = Math.min(STUCK_PROGRESS_PX, Math.max(2, expectedProgress * 0.45));
        enemy.aiState.stuckMs = progressed < progressThreshold ? enemy.aiState.stuckMs + STUCK_CHECK_WINDOW_MS : 0;
        if (typeStats.erratic && enemy.aiState.stuckMs >= STUCK_RETREAT_AFTER_MS) {
          // A player-chasing Scout that cannot make net progress disengages
          // promptly, then approaches again instead of oscillating at the
          // same corner or firing slot.
          enemy.aiState.retreatMs = Math.max(enemy.aiState.retreatMs, typeStats.retreatDurationMs);
          enemy.aiState.stuckMs = 0;
        }
        enemy.aiState.checkX = enemy.x;
        enemy.aiState.checkY = enemy.y;
        enemy.aiState.checkTimerMs += STUCK_CHECK_WINDOW_MS;
      }
    }

    // Movement identity stays unchanged: Heavy/Titan continue pressuring the
    // base and Artillery keeps its standoff ring. Their weapon independently
    // retaliates against a nearby player, so intercepting a large tank is a
    // fight rather than safe target practice.
    const playerDistance = distance(enemy, player);
    const playerAngle = Math.atan2(player.y - enemy.y, player.x - enemy.x);
    const insideRetaliationArc = !typeStats.retaliationFrontHalfAngleDeg ||
      Math.abs(normalizeAngle(playerAngle - enemy.heading)) <=
        (typeStats.retaliationFrontHalfAngleDeg * Math.PI) / 180;
    const canRetaliate = Boolean(typeStats.retaliationRange) &&
      player.hp > 0 &&
      playerDistance <= typeStats.retaliationRange &&
      insideRetaliationArc &&
      (typeStats.arcsWalls || hasLineOfSight(grid, enemy.x, enemy.y, player.x, player.y));
    const weaponTarget = canRetaliate ? player : targetEntity;
    enemy.aiState.targetingPlayer = weaponTarget === player;
    const desiredWeaponHeading = Math.atan2(weaponTarget.y - enemy.y, weaponTarget.x - enemy.x);
    const turretTurnSpeed = ((typeStats.turretTurnSpeedDeg ?? 0) * Math.PI) / 180;
    if (turretTurnSpeed > 0) {
      const currentTurretHeading = enemy.turretHeading ?? enemy.heading;
      const turn = clamp(normalizeAngle(desiredWeaponHeading - currentTurretHeading), -turretTurnSpeed * dtSec, turretTurnSpeed * dtSec);
      enemy.turretHeading = normalizeAngle(currentTurretHeading + turn);
    } else {
      enemy.turretHeading = enemy.heading;
    }
    let weaponHeading = turretTurnSpeed > 0 ? enemy.turretHeading : enemy.heading;
    let weaponAligned = Math.abs(normalizeAngle(desiredWeaponHeading - weaponHeading)) <=
      ((turretTurnSpeed > 0 ? 7 : typeStats.visionAngleDeg) * Math.PI) / 180;

    const canPrepareShot = !typeStats.arcsWalls || enemy.aiState.deployed;
    if (canPrepareShot) enemy.fireCooldownMs = Math.max(0, enemy.fireCooldownMs - dtMs);
    if (enemy.fireCooldownMs <= 0) {
      if (typeStats.arcsWalls) {
        if (enemy.aiState.deployed && weaponAligned && distance(enemy, weaponTarget) <= typeStats.range) {
          bullets.push(createArcShell(nextEntityId, "enemy", enemy, weaponTarget, typeStats));
          events.push({
            type: EVENTS.ENEMY_FIRED,
            x: enemy.x,
            y: enemy.y,
            angle: weaponHeading,
            enemyType: enemy.type,
            target: weaponTarget === player ? "player" : "base",
          });
          nextEntityId += 1;
          enemy.fireCooldownMs = typeStats.fireCooldownMs *
            (enemy.fireCooldownMultiplier ?? 1) *
            (weaponTarget === player ? typeStats.retaliationCooldownMultiplier ?? 1 : 1);
        }
      } else {
        const dx = weaponTarget.x - enemy.x;
        const dy = weaponTarget.y - enemy.y;
        const dist = Math.hypot(dx, dy);
        const angleTo = Math.atan2(dy, dx);
        const targetRadius = weaponTarget.radius ?? PLAYER_STATS.radius;
        // Once a direct-fire enemy reaches its target, tiny collision/sliding
        // adjustments can make steerToward flip its hull away every frame.
        // Snap to the target at point-blank range so a Heavy cannot overlap
        // the base indefinitely with a ready weapon but never attack.
        if (dist <= typeStats.radius + targetRadius + 4 && weaponTarget === targetEntity) {
          enemy.heading = angleTo;
          enemy.turretHeading = angleTo;
          weaponHeading = angleTo;
          weaponAligned = true;
        }
        if (dist <= typeStats.range && weaponAligned && hasLineOfSight(grid, enemy.x, enemy.y, weaponTarget.x, weaponTarget.y)) {
          bullets.push(createBullet(nextEntityId, "enemy", enemy.x, enemy.y, weaponHeading, typeStats));
          events.push({
            type: EVENTS.ENEMY_FIRED,
            x: enemy.x,
            y: enemy.y,
            angle: weaponHeading,
            enemyType: enemy.type,
            target: weaponTarget === player ? "player" : "base",
          });
          nextEntityId += 1;
          enemy.fireCooldownMs = typeStats.fireCooldownMs *
            (enemy.fireCooldownMultiplier ?? 1) *
            (weaponTarget === player ? typeStats.retaliationCooldownMultiplier ?? 1 : 1);
          if (typeStats.retreatDurationMs && weaponTarget === player) {
            enemy.aiState.retreatMs = typeStats.retreatDurationMs;
          }
        }
      }
    }

    // Telegraph: for types with a telegraphMs window, flag the final
    // stretch of the reload as "winding up" so the renderer can show an
    // aim/warning cue before the shot actually fires - not just a bullet
    // appearing with no warning.
    const telegraphMs = typeStats.telegraphMs ?? 0;
    // Arcing types (Artillery) must be fully deployed before a windup can
    // mean anything - their cooldown keeps counting down while approaching.
    // Direct-fire types with a telegraph (Scout) have no separate deploy
    // phase, so the cooldown window alone is enough to flag the cue.
    const readyToTelegraph = typeStats.arcsWalls ? Boolean(enemy.aiState.deployed) : true;
    enemy.aiState.windingUp = !(battleAdvantage?.type === "relay" && battleAdvantage.remainingMs > 0 && enemy.type === "artillery") && readyToTelegraph &&
      telegraphMs > 0 && enemy.fireCooldownMs > 0 && enemy.fireCooldownMs <= telegraphMs;
    enemy.aiState.aimProgress = enemy.aiState.windingUp ? clamp(1 - enemy.fireCooldownMs / telegraphMs, 0, 1) : 0;
  }

  // Resolve every mobile body against other tanks and the fixed base after
  // movement, before combat is evaluated.
  resolveTankCollisions(player, enemies, grid, level.hasBase === false ? null : base);

  // One deliberate lane-denial tool per sortie. Mines are visible, remain
  // where dropped, and trigger only when an enemy actually crosses them.
  const survivingMines = [];
  for (const mine of mines) {
    const tripped = enemies.some((enemy) =>
      enemy.hp > 0 &&
      distance(mine, enemy) <= TACTICAL_RULES.mineTriggerRadius + ENEMY_TYPES[enemy.type].radius
    );
    if (!tripped) {
      survivingMines.push(mine);
      continue;
    }
    events.push({ type: EVENTS.MINE_DETONATED, x: mine.x, y: mine.y });
    // Everything inside the blast, not only whatever tripped it.
    const caught = enemies.filter((enemy) =>
      enemy.hp > 0 &&
      distance(mine, enemy) <= TACTICAL_RULES.mineBlastRadius + ENEMY_TYPES[enemy.type].radius &&
      // Cover stops a blast, exactly as it stops a shell. Distance alone let
      // a mine kill through intact steel, which contradicts every other
      // damage source in the game and the one thing cover is for.
      hasLineOfSight(grid, mine.x, mine.y, enemy.x, enemy.y)
    );
    for (const hitEnemy of caught) {
      hitEnemy.hp -= TACTICAL_RULES.mineDamage;
      if (hitEnemy.hp <= 0) {
        stats.enemiesDefeated += 1;
        events.push({
          type: EVENTS.ENEMY_DESTROYED,
          x: hitEnemy.x,
          y: hitEnemy.y,
          enemyType: hitEnemy.type,
          source: "mine",
          ace: hitEnemy.ace ? { ...hitEnemy.ace } : null,
        });
        if (hitEnemy.ace) {
          events.push({ type: EVENTS.ACE_DESTROYED, x: hitEnemy.x, y: hitEnemy.y, ace: { ...hitEnemy.ace } });
        }
        if (hitEnemy.drop) {
          pickups.push({ id: nextEntityId, kind: hitEnemy.drop, x: hitEnemy.x, y: hitEnemy.y, ttlMs: 9_000 });
          nextEntityId += 1;
        }
      }
    }
  }
  mines = survivingMines;

  // Bullets: move, resolve terrain/entity collisions, apply damage.
  const survivingBullets = [];
  for (const bullet of bullets) {
    if (bullet.arcsWalls) {
      bullet.travelMs += dtMs;
      const progress = Math.min(1, bullet.travelMs / bullet.totalTravelMs);
      bullet.x = bullet.originX + (bullet.targetX - bullet.originX) * progress;
      bullet.y = bullet.originY + (bullet.targetY - bullet.originY) * progress;
      if (progress >= 1) {
        if (distance(bullet, player) <= bullet.blastRadius + PLAYER_STATS.radius) {
          if (player.powerups.shield > 0) {
            events.push({ type: EVENTS.SHIELD_BLOCKED, x: player.x, y: player.y });
          } else {
            player.hp -= bullet.damage;
            events.push({ type: EVENTS.PLAYER_DAMAGED, x: player.x, y: player.y, sourceX: bullet.originX, artillery: true });
          }
        }
        if (distance(bullet, base) <= bullet.blastRadius + base.radius) {
          base.hp -= bullet.damage;
          events.push({ type: EVENTS.BASE_DAMAGED, x: base.x, y: base.y, sourceX: bullet.originX, artillery: true });
        }
        continue;
      }
      survivingBullets.push(bullet);
      continue;
    }

    const nextBulletX = bullet.x + bullet.vx * dtSec;
    const nextBulletY = bullet.y + bullet.vy * dtSec;
    const hit = traceProjectileBlocker(
      grid,
      bullet.x,
      bullet.y,
      nextBulletX,
      nextBulletY,
      bullet.radius,
    );
    if (hit) {
      if (
        hit.type === "#" &&
        bullet.owner === "player" &&
        bullet.ammoMode === "he" &&
        bullet.destroysBrick === true
      ) {
        grid = setCell(grid, hit.row, hit.col, ".");
        events.push({
          type: EVENTS.BRICK_DESTROYED,
          x: hit.col * TILE + TILE / 2,
          y: hit.row * TILE + TILE / 2,
        });
      } else {
        events.push({
          type: EVENTS.PROJECTILE_BLOCKED,
          x: hit.x,
          y: hit.y,
          material: hit.type,
          owner: bullet.owner,
        });
      }
      continue;
    }
    bullet.x = nextBulletX;
    bullet.y = nextBulletY;

    if (bullet.owner === "player") {
      const hitEnemy = enemies.find((enemy) => enemy.hp > 0 && distance(bullet, enemy) <= bullet.radius + ENEMY_TYPES[enemy.type].radius);
      if (hitEnemy) {
        if (isBossFrontArmorHit(hitEnemy, bullet)) {
          events.push({
            type: EVENTS.BOSS_ARMOR_BLOCKED,
            x: bullet.x,
            y: bullet.y,
            angle: Math.atan2(bullet.vy, bullet.vx),
          });
          continue;
        }
        const affectedEnemies = bullet.blastRadius > 0
          ? enemies.filter((enemy) => enemy.hp > 0 && distance(bullet, enemy) <= bullet.blastRadius + ENEMY_TYPES[enemy.type].radius)
          : [hitEnemy];
        for (const affected of affectedEnemies) {
          // The Titan's exposed rear is a true weak point. Ordinary tanks
          // still lose exactly one visible armour pip per direct AP hit.
          const damage = affected.sentry && bullet.ammoMode === "he"
            ? bullet.damage * 3
            : affected.type === "boss" && bullet.ammoMode === "ap"
            ? bullet.damage * 2
            : bullet.damage;
          affected.hp -= damage;
          stats.shotsHit += 1;
          events.push({ type: EVENTS.PLAYER_SHOT_HIT, x: affected.x, y: affected.y, ammoMode: bullet.ammoMode, weakPoint: affected.type === "boss" && bullet.ammoMode === "ap" });
          if (affected.hp <= 0) {
            stats.enemiesDefeated += 1;
            events.push({
              type: EVENTS.ENEMY_DESTROYED,
              x: affected.x,
              y: affected.y,
              enemyType: affected.type,
              source: "shell",
              ammoMode: bullet.ammoMode,
              ace: affected.ace ? { ...affected.ace } : null,
            });
            if (affected.ace) {
              events.push({ type: EVENTS.ACE_DESTROYED, x: affected.x, y: affected.y, ace: { ...affected.ace } });
            }
            if (affected.drop) {
              pickups.push({ id: nextEntityId, kind: affected.drop, x: affected.x, y: affected.y, ttlMs: 9_000 });
              nextEntityId += 1;
            }
          }
        }
        continue;
      }
    } else if (bullet.owner === "enemy") {
      if (distance(bullet, player) <= bullet.radius + PLAYER_STATS.radius) {
        if (player.powerups.shield > 0) {
          events.push({ type: EVENTS.SHIELD_BLOCKED, x: player.x, y: player.y });
        } else {
          player.hp -= bullet.damage;
          events.push({ type: EVENTS.PLAYER_DAMAGED, x: player.x, y: player.y, sourceX: bullet.originX, artillery: false });
        }
        continue;
      }
      if (distance(bullet, base) <= bullet.radius + base.radius) {
        base.hp -= bullet.damage;
        events.push({ type: EVENTS.BASE_DAMAGED, x: base.x, y: base.y, sourceX: bullet.originX, artillery: false });
        continue;
      }
    }
    survivingBullets.push(bullet);
  }
  bullets = survivingBullets;
  enemies = enemies.filter((enemy) => enemy.hp > 0);

  if (
    secondaryObjective?.type === "ace-hunt" &&
    !secondaryObjective.completed &&
    events.some((event) => event.type === EVENTS.ACE_DESTROYED)
  ) {
    secondaryObjective.completed = true;
    events.push({ type: EVENTS.OBJECTIVE_COMPLETED, objectiveType: secondaryObjective.type });
  }

  // Power-up pickups: countdown, collection.
  const survivingPickups = [];
  for (const pickup of pickups) {
    if (distance(pickup, player) <= 20) {
      player.powerups[pickup.kind] = POWERUP_TYPES[pickup.kind].durationMs;
      events.push({ type: EVENTS.POWERUP_COLLECTED, kind: pickup.kind, x: pickup.x, y: pickup.y });
      continue;
    }
    pickup.ttlMs -= dtMs;
    if (pickup.ttlMs <= 0) continue;
    survivingPickups.push(pickup);
  }
  pickups = survivingPickups;

  // Spawn plan.
  const elapsedMs = state.elapsedMs + dtMs;
  const completedNow = secondaryObjective?.completed && !state.secondaryObjective?.completed;
  let spawnPlan = state.spawnPlan;
  if (completedNow) {
    const type = secondaryObjective.type;
    const message = type === "relay" ? "ARTILLERY JAMMED · 8s"
      : type === "sapper" ? spawnPlan.length ? "REINFORCEMENTS DELAYED · 6s" : "RESERVE MINE READY"
        : enemies.length ? "ENEMY RELOAD DISRUPTED · 4s" : "ACE DOWN · ROAD CLEAR";
    battleAdvantage = { type, remainingMs: type === "relay" ? 8000
      : type === "sapper" ? spawnPlan.length ? 6000 : 0
        : enemies.length ? 4000 : 0, message };
    if (type === "sapper") spawnPlan = spawnPlan.map(entry => ({ ...entry, delayMs: entry.delayMs + 6000 }));
    if (type === "sapper" && spawnPlan.length === 0) player.minesRemaining += 1;
    if (type === "ace-hunt") for (const enemy of enemies) enemy.fireCooldownMs = Math.max(4000, enemy.fireCooldownMs);
    events.push({ type: EVENTS.BATTLE_ADVANTAGE, message, x: player.x, y: player.y });
  }
  const damageEvent = events.filter(e => base.hp <= 0 ? e.type === EVENTS.BASE_DAMAGED
    : player.hp <= 0 ? e.type === EVENTS.PLAYER_DAMAGED
    : e.type === EVENTS.PLAYER_DAMAGED || e.type === EVENTS.BASE_DAMAGED).at(-1);
  const lastDamage = damageEvent ? { ...damageEvent, elapsedMs } : state.lastDamage;
  let remainingPlan = [];
  for (const entry of spawnPlan) {
    // A level with a prep phase holds its whole spawn plan back, so the
    // board belongs to the player until the clock runs out.
    if (entry.delayMs + (level.prepMs ?? 0) <= elapsedMs) {
      const spawnPoint = level.spawnPoints[entry.spawnPointIndex];
      enemies.push(createEnemy(nextEntityId, entry.type, spawnPoint, entry.drop, entry.ace));
      nextEntityId += 1;
    } else {
      remainingPlan.push(entry);
    }
  }

  let phase = state.phase;
  let result = state.result;
  let endlessWave = state.endlessWave ?? 0;
  if (base.hp <= 0 && !level.extraction) {
    phase = "ended";
    result = { outcome: "lost", reason: "base-destroyed", elapsedMs };
  } else if (player.hp <= 0) {
    phase = "ended";
    result = { outcome: "lost", reason: "player-destroyed", elapsedMs };
  } else if (escort && escort.checkpoint === level.escortRoute.length) {
    phase = "ended";
    result = { outcome: "won", reason: "convoy-arrived", elapsedMs };
  } else if (currentStage.extraction && distance(player, currentStage.extraction) <= currentStage.extraction.radius) {
    if (stage + 1 < stageCount(level)) {
      // Break into the next section rather than ending. Damage, elapsed time
      // and mines carry across - the run is one continuous thing, and a fresh
      // tank at every gate would make the length free.
      const nextStage = stageOf(level, stage + 1);
      stage += 1;
      grid = [...nextStage.grid];
      player.x = nextStage.playerSpawn.x;
      player.y = nextStage.playerSpawn.y;
      player.heading = -Math.PI / 2;
      player.terrain = terrainAt(grid, player.x, player.y);
      player.stationaryMs = 0;
      player.braced = false;
      bullets = [];
      mines = [];
      pickups = [];
      const nextRules = sentryRulesFor(level, stage);
      enemies = (nextStage.sentries ?? []).map((position, index) => makeSentry(nextEntityId + index, position, nextRules, level));
      nextEntityId += enemies.length;
      events.push({ type: EVENTS.LABYRINTH_STAGE_CLEARED, stage: stage + 1,
        stageCount: stageCount(level), stageName: nextStage.name ?? level.name });
    } else {
      phase = "ended";
      remainingPlan = [];
      result = { outcome: "won", reason: "extracted", elapsedMs };
    }
  } else if (!level.extraction && !escort && remainingPlan.length === 0 && enemies.length === 0) {
    if (state.endless) {
      endlessWave += 1;
      remainingPlan = createEndlessWave(level, endlessWave, elapsedMs);
      events.push({ type: EVENTS.ENDLESS_WAVE_STARTED, wave: endlessWave });
    } else {
      phase = "ended";
      result = { outcome: "won", elapsedMs };
    }
  }

  return {
    ...state,
    phase,
    elapsedMs,
    stage,
    grid,
    rngSeed,
    nextEntityId,
    player,
    enemies,
    bullets,
    mines,
    powerupPickups: pickups,
    base,
    secondaryObjective,
    battleAdvantage,
    escort,
    lastDamage,
    secretCache,
    endlessWave,
    spawnPlan: remainingPlan,
    stats,
    events,
    result,
  };
}

// What a run reports has to match what the run was about. A mode with no
// base still reported base health, so the result screen said "Base 99/99"
// for a base its own briefing says does not exist. Where there is no base,
// the player's hull is the thing at stake - the guns are the whole hazard.
function gradedHealth(state) {
  const level = levelById(state.levelId);
  return level.hasBase === false
    // The tank's own maximum, not the type default. Buying Field Armour raises
    // maxHp, and dividing by the default instead scored an untouched 5/5 run
    // below an untouched 4/4 one - spending Supply Points cost you a star.
    ? { hp: state.player.hp, maxHp: state.player.maxHp ?? PLAYER_STATS.maxHp, baseHpRemaining: null }
    : { hp: state.base.hp, maxHp: state.base.maxHp, baseHpRemaining: state.base.hp };
}

export function computeGrade(state) {
  if (!state.result || state.result.outcome !== "won") {
    const lost = gradedHealth(state);
    return { stars: 0, timeMs: state.elapsedMs, baseHpRemaining: lost.baseHpRemaining, hpRemaining: lost.hp };
  }
  const level = levelById(state.levelId);
  const graded = gradedHealth(state);
  const healthRatio = graded.hp / graded.maxHp;
  const fast = state.elapsedMs <= level.parTimeMs;
  let stars = 1;
  if (healthRatio === 1 && fast) stars = 3;
  else if (healthRatio >= 0.6 || fast) stars = 2;
  return { stars, timeMs: state.elapsedMs, baseHpRemaining: graded.baseHpRemaining, hpRemaining: graded.hp };
}
